using BlockDock;
using System.IO;
using System.IO.Compression;
using System.Text.Json.Nodes;
using System.Windows.Media.Imaging;

static class ConfigurationChecks
{
    static void Check(bool value,string label){if(!value)throw new Exception("FAIL: "+label);Console.WriteLine("PASS: "+label);}
    public static void Run()
    {
        Check(new Settings().MemoryMode=="Auto","memory allocation defaults to automatic");var ample=new MemorySnapshot(32768,24000);Check(MemoryAllocation.Calculate(ample,true,0,"Auto",512)==3072&&MemoryAllocation.Calculate(ample,true,210,"Auto",512)==6144,"automatic memory adapts to vanilla and large modpacks");Check(MemoryAllocation.Calculate(new(8192,2048),true,210,"Auto",8192)==4096&&MemoryAllocation.Calculate(new(16384,2048),true,212,"Auto",8192)==6144&&MemoryAllocation.Calculate(new(16384,14000),true,212,"Auto",8192)==6144,"large modpack heap depends on total RAM and stays stable when free memory drops");Check(MemoryAllocation.Calculate(ample,true,210,"Manual",5632)==5632&&MemoryAllocation.Calculate(ample,true,210,"Manual",8192,true)==1024,"manual memory is preserved and 32-bit Java is bounded");
        string settingsFile=Path.Combine(Settings.DataPath,"settings.json");string? old=File.Exists(settingsFile)?File.ReadAllText(settingsFile):null;try{new Settings{MemoryMode="Manual",MemoryMb=5632}.Save();var loaded=Settings.Load();Check(loaded.MemoryMode=="Manual"&&loaded.MemoryMb==5632,"manual allocation survives settings reload");Settings.AtomicText(settingsFile,"{\"MemoryProfile\":\"High\",\"MemoryMb\":8192}");Check(Settings.Load().MemoryMode=="Auto","old performance presets migrate to automatic allocation");}finally{if(old!=null)Settings.AtomicText(settingsFile,old);else if(File.Exists(settingsFile))File.Delete(settingsFile);}
        string root=Path.GetFullPath("work/config-checks");Directory.CreateDirectory(root);string png=Path.GetFullPath("src/Assets/BlockDock.png");Check(File.Exists(png),"launcher icon asset exists");var frame=BitmapFrame.Create(new Uri(png));var rgba=new System.Windows.Media.Imaging.FormatConvertedBitmap(frame,System.Windows.Media.PixelFormats.Bgra32,null,0);byte[] corner=new byte[4];rgba.CopyPixels(new System.Windows.Int32Rect(0,0,1,1),corner,4,0);Check(frame.PixelWidth>=1024&&frame.PixelHeight>=1024&&corner[3]==0,"high-resolution launcher image retains transparent background");using(var input=File.OpenRead(Path.ChangeExtension(png,"ico"))){var ico=BitmapDecoder.Create(input,BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.OnLoad);Check(ico.Frames.Count==7&&ico.Frames.Any(x=>x.PixelWidth==256)&&ico.Frames.Any(x=>x.PixelWidth==16),"Windows icon contains seven valid sizes including 16 and 256 pixels");}
        // APPX logo bounds are independent from the launcher's large source artwork.
        var logo=new PngBitmapEncoder();logo.Frames.Add(BitmapFrame.Create(BitmapSource.Create(16,16,96,96,System.Windows.Media.PixelFormats.Bgra32,null,Enumerable.Repeat((byte)255,16*16*4).ToArray(),64)));
        using var logoData=new MemoryStream();logo.Save(logoData);
        string package=Path.Combine(root,"icon-fixture.appx");if(File.Exists(package))File.Delete(package);using(var zip=ZipFile.Open(package,ZipArchiveMode.Create)){using(var writer=new StreamWriter(zip.CreateEntry("AppxManifest.xml").Open()))writer.Write("<Package xmlns:u='urn:fixture'><Applications><Application><u:VisualElements Square44x44Logo='Assets\\Logo.png'/></Application></Applications></Package>");using var stream=zip.CreateEntry("Assets/Logo.scale-200.png").Open();stream.Write(logoData.ToArray());}Check(BedrockIcons.Get(package) is BitmapSource,"Bedrock reads manifest icon with scale-qualified filename");
        string? sample=Environment.GetEnvironmentVariable("BLOCKDOCK_BEDROCK_ICON_SAMPLE");if(sample!=null){var icon=BedrockIcons.Get(sample);Check(icon is BitmapSource,"existing Minecraft APPX provides its original application icon");var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create((BitmapSource)icon));using var output=File.Create(Path.Combine(root,"bedrock-actual-icon.png"));encoder.Save(output);}
    }
    public static async Task ProfileAsync()
    {
        string root=Path.GetFullPath("work/config-checks/java");void Version(string id,string json){string folder=Path.Combine(root,"versions",id);Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,id+".json"),json);}
        Version("base","""{"id":"base","type":"release","mainClass":"net.minecraft.client.main.Main","time":"2024-01-01T00:00:00Z","releaseTime":"2024-01-01T00:00:00Z","javaVersion":{"majorVersion":17},"arguments":{"game":["base-game"],"jvm":["base-jvm"]},"libraries":[]}""");
        Version("fabric","""{"id":"fabric","inheritsFrom":"base","mainClass":"net.fabricmc.loader.impl.launch.knot.KnotClient","arguments":{"jvm":["fabric-jvm"]},"libraries":[{"name":"example:loader:1"}]}""");Version("bridge","""{"id":"bridge","inheritsFrom":"fabric","arguments":{"jvm":["bridge-jvm"]},"libraries":[{"name":"example:bridge:1"}]}""");var profile=VersionProfiles.Create(root,"bridge","alias");Check(profile["inheritsFrom"]!.ToString()=="base"&&profile["mainClass"]!.ToString().Contains("KnotClient")&&profile["jar"]!.ToString()=="base"&&profile["type"]!.ToString()=="release","named loader instance has one vanilla parent and explicit main class/client JAR");Check(profile["libraries"]!.AsArray().Count==2&&profile["arguments"]!["jvm"]!.AsArray().Count==2,"flattening preserves loader libraries and JVM arguments");Version("alias",profile.ToJsonString());using var core=new LaunchCore(new Settings{JavaRoot=root});var launcher=core.CreateLauncher(localOnly:true);var parsed=await launcher.GetVersionAsync("alias");Check(parsed.MainJarId=="base"&&parsed.MainClass!.Contains("KnotClient")&&parsed.ParentVersion?.Id=="base","launcher parser resolves shared vanilla client and Fabric entry point");
        string alias=Path.Combine(root,"versions","alias");File.WriteAllText(Path.Combine(alias,"alias.json"),"{\"id\":\"alias\",\"inheritsFrom\":\"bridge\",\"type\":\"custom\"}");File.WriteAllText(Path.Combine(alias,".blockdock-profile.json"),"{\"sourceVersion\":\"bridge\"}");Directory.CreateDirectory(Path.Combine(alias,"mods"));File.WriteAllText(Path.Combine(alias,"mods","keep.jar"),"fixture");core.RepairInstanceProfile(new("alias","alias","base","fabric",alias,alias));Check(JsonNode.Parse(File.ReadAllText(Path.Combine(alias,"alias.json")))?["mainClass"]!=null&&File.ReadAllText(Path.Combine(alias,"mods","keep.jar"))=="fixture","repair replaces only owned minimal version profile and keeps mod files");
    }
    public static async Task PrepareProfileAsync()
    {
        string root=Environment.GetEnvironmentVariable("BLOCKDOCK_PROFILE_ROOT")??throw new Exception("Missing profile root");string id=Paths.Id(Environment.GetEnvironmentVariable("BLOCKDOCK_PROFILE_ID")??throw new Exception("Missing instance id"));string folder=Paths.Safe(root,"versions/"+id);string source=JsonNode.Parse(File.ReadAllText(Path.Combine(folder,".blockdock-profile.json")))!["sourceVersion"]!.ToString();var profile=VersionProfiles.Create(root,source,id);string draft=Path.GetFullPath("work/profile-repair/"+id+".json");Settings.AtomicText(draft,profile.ToJsonString(new(){WriteIndented=true}));string fixture=Path.GetFullPath("work/profile-repair/validate");Directory.CreateDirectory(Path.Combine(fixture,"versions",id));File.Copy(draft,Path.Combine(fixture,"versions",id,id+".json"),true);string parent=profile["inheritsFrom"]!.ToString();Directory.CreateDirectory(Path.Combine(fixture,"versions",parent));File.Copy(Path.Combine(root,"versions",parent,parent+".json"),Path.Combine(fixture,"versions",parent,parent+".json"),true);using var core=new LaunchCore(new Settings{JavaRoot=fixture});var launcher=core.CreateLauncher(localOnly:true);var parsed=await launcher.GetVersionAsync(id);Check(parsed.MainClass?.Contains("KnotClient")==true&&parsed.MainJarId==parent,"repaired existing instance metadata parses with correct Fabric entry and vanilla client");Console.WriteLine("PREPARED_PROFILE="+draft);
    }
    public static void DescribeExistingMemory()
    {
        string root=Environment.GetEnvironmentVariable("BLOCKDOCK_PROFILE_ROOT")??throw new Exception("Missing profile root");string id=Environment.GetEnvironmentVariable("BLOCKDOCK_PROFILE_ID")??throw new Exception("Missing instance id");var settings=new Settings{JavaRoot=root};var game=LaunchCore.Scan(settings).Single(x=>x.Id==id);var memory=MemoryAllocation.Snapshot();int count=Directory.Exists(Path.Combine(game.GameDirectory,"mods"))?Directory.GetFiles(Path.Combine(game.GameDirectory,"mods"),"*.jar").Length:0;Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(new{Instance=id,Mods=count,TotalMb=memory.TotalMb,AvailableMb=memory.AvailableMb,AllocatedMb=MemoryAllocation.Resolve(settings,game,memory)}));
    }
}
